        try {
            // Get the Class object for MyClass
            Class<?> myClass = Class.forName("MyClass");

            // Get the declared no-argument constructor and instantiate it
            Object obj = myClass.getDeclaredConstructor().newInstance();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
