### 1. The Custom Hook (`useList.ts`)

```typescript
import { useState, useCallback } from 'react';

// Define the type for the update payload, which requires an 'id' to find the item
// and allows any subset of the item's properties to be updated.
export type UpdatePayload<T> = Partial<T> & Pick<T, 'id'>;

function useList<T extends { id: string | number }>(initialItems: T[] = []) {
  const [items, setItems] = useState<T[]>(initialItems);

  // Add a single item to the end of the list
  const addItem = useCallback((item: T) => {
    setItems((prev) => [...prev, item]);
  }, []);

  // Add multiple items to the end of the list
  const addItems = useCallback((newItems: T[]) => {
    setItems((prev) => [...prev, ...newItems]);
  }, []);

  // Remove an item by its id
  const removeItem = useCallback((id: T['id']) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  }, []);

  // Update an item by merging the new properties into the existing item
  const updateItem = useCallback((payload: UpdatePayload<T>) => {
    setItems((prev) =>
      prev.map((item) =>
        item.id === payload.id ? { ...item, ...payload } : item
      )
    );
  }, []);

  // Clear all items from the list
  const clearItems = useCallback(() => {
    setItems([]);
  }, []);

  return {
    items,
    addItem,
    addItems,
    removeItem,
    updateItem,
    clearItems,
  };
}

export default useList;
```

