public class PdfConverter
{
    /// <summary>
    /// Converts a PDF file to a Base64 string.
    /// </summary>
    /// <param name="filePath">The full path to the PDF file.</param>
    /// <returns>A Base64 representation of the PDF file.</returns>
    public static string ConvertPdfToBase64(string filePath)
    {
        // 1. Check if the file exists
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The specified PDF file was not found.", filePath);
        }

        // 2. Read the PDF file as a byte array
        byte[] pdfBytes = File.ReadAllBytes(filePath);

        // 3. Convert the byte array to a Base64 string
        return Convert.ToBase64String(pdfBytes);
    }
}
